                move_best = score

        # Global tie-breaker: prefer moves that keep us nearer to the closest resource
        if move_best > best_score:
            best_score = move_best
            best = [dx, dy]
        elif move_best == best_score:
            cur_ds_best = 10**9
            best_ds = 10**9
            for rx, ry, _do in res_info:
