                ds2 = man(nx, ny, rx, ry)
                if ds1 < best_ds:
                    best_ds = ds1
                if ds2 < cur_ds_best:
                    cur_ds_best = ds2
            if cur_ds_best < best_ds:
                best = [dx, dy]

